create or replace TABLE KFL_PRODUCTION.DBP_DATA.SAL_KMO (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Monat eines Kalenderjahres, Format JJJJMM',
	ARTHIERTYP_ID NUMBER(38,0) COMMENT 'Artikel - Hierarchie - Typ - ID. Kennzeichnet',
	WG_ID NUMBER(38,0) COMMENT 'ID der Warengruppe',
	WUG_ID NUMBER(38,0) COMMENT 'Warenuntergruppe (WGI)',
	ART_STATUS VARCHAR(2) COLLATE 'en-ci' COMMENT 'Wenn Artikel aktuell in mind. einem Markt gelistet ist (Abfrage über dbp_data.sternchen_logik sum(anzahl_markt_listung)>0), dann ist das Flag gesetzt',
	GP_ID NUMBER(38,0) COMMENT 'Geschäftspartner - ID (Lieferanten - ID)',
	GP_NAME VARCHAR(40) COLLATE 'en-ci' COMMENT 'Bezeichnung des Geschäftspartners',
	EIGENMARKE_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Eigenmarken-Kennzeichen (z.Bsp. C für Kaufland Klassikartikel)',
	BIO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Biosiegel Flag EU, es gibt auch noch ein bio_fg_cz (Kürzel: BIO)',
	VEGAN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Vegan Flag aus vgn (Kürzel: VGN)',
	POSTEN_FOOD VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Postenkennzeichen. Für Artikel, die nicht ständig im Sortiment sind',
	POSTEN_NONFOOD VARCHAR(1) NOT NULL COLLATE 'en-ci',
	GLUTEN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Gluten-freie Artikel',
	MWST NUMBER(12,2) NOT NULL COMMENT 'Mehrwertsteuersatz',
	DISC_PE NUMBER(38,0) COMMENT 'Discount Kennzeichen PE (Herkunft noch klären!)',
	DISC_MARKE NUMBER(38,0),
	LACTOSE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Lactosefreie Artikel',
	K_LISTUNG VARCHAR(4) NOT NULL COLLATE 'en-ci',
	UMRECH_FAKTOR_BEST NUMBER(38,5) NOT NULL COMMENT 'Umrechnungsfaktor für eine alternative Mengenheinheit zur Umrechnung einer Basismenge in diese Mengeneinheit.',
	UMRECH_FAKTOR_AUSG NUMBER(38,5) NOT NULL COMMENT 'Umrechnungsfaktor für eine alternative Mengenheinheit zur Umrechnung einer Basismenge in diese Mengeneinheit.',
	MHD_ZEITRAUM NUMBER(38,0) COMMENT 'Dieses Feld gibt den standardmässigen Mindesthaltbarkeitszeitraum für diesen Artikel in Tagen an.',
	MHD_ZEITRAUM_DZ NUMBER(38,0),
	K1_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung für die Listung K1 (sm_id(kann in Stück oder bei Gewichtsartikeln in KG sein) ',
	K1_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz in der Listung K1 für diesen Artikel',
	K2_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung (kann in Stück oder bei Gewichtsartikeln in KG sein). Anzahl der abverkauften Artikel reduziert um zurückgegebene Artikel',
	K2_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz in der Listung K2 für diesen Artikel',
	K3_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung für die Listung K3 (sm_id(kann in Stück oder bei Gewichtsartikeln in KG sein) ',
	K3_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz in der Listung K3 für diesen Artikel',
	K4_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung für die Listung K4 (sm_id(kann in Stück oder bei Gewichtsartikeln in KG sein) ',
	K4_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz in der Listung K4 für diesen Artikel',
	K5_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung für die Listung K5 (sm_id(kann in Stück oder bei Gewichtsartikeln in KG sein) ',
	K5_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz in der Listung K5 für diesen Artikel',
	TOTAL_ARTBEW_MENGE NUMBER(18,3) COMMENT 'Menge der Artikelbewegung (sm_id(kann in Stück oder bei Gewichtsartikeln in KG sein) ',
	TOTAL_ANZ_KJWO_WUG_ABSATZ NUMBER(38,0) COMMENT 'Anzahl Wochen mit Umsatz für diesen Artikel',
	TOTAL_ARTBEW_MENGE_VJ NUMBER(18,3),
	TOTAL_ARTBEW_MENGE_SA NUMBER(18,3),
	TOTAL_ANZ_KJWO_WUG_ABSATZ_SA NUMBER(38,0),
	TOTAL_ANZ_TAGE_WUG_ABSATZ_SA NUMBER(38,0),
	TOTAL_ARTBEW_MENGE_AF NUMBER(18,3),
	TOTAL_ANZ_KJWO_WUG_ABSATZ_AF NUMBER(38,0),
	SCHNELLDREHERQUOTE NUMBER(38,5) NOT NULL COMMENT 'Anzahl Wochen mit Absatz/Anzahl Wochen mit Listung',
	PROZENTUAL_ABSATZ_SA NUMBER(38,5) NOT NULL COMMENT 'Anteil Sonderaktionsmege in Prozent',
	TOTAL_ROHERTRAG NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis ) für den kompletten Umsatz.',
	TOTAL_ROHERTRAG_VJ NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy,
	TOTAL_ROHERTRAG_AF NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis) für den aktionsfreien Umsatz (bewart_id 1001) / total_artbew_menge',
	TOTAL_ROHERTRAG_SA NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis) für den Sonderaktions-Umsatz (bewart_id 1002) / total_artbew_menge',
	ROHERTRAG_EINHEIT NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis ) für den kompletten Umsatz / total_artbew_menge',
	ROHERTRAG_EINHEIT_AF NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis ) für den kompletten Umsatz',
	ROHERTRAG_EINHEIT_SA NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy COMMENT 'Umsatz_netto abzgl. EK_MEP (Markteinstandspreis ) für den kompletten Umsatz',
	ABSCHRIFTBETRAG_NETTO_OWERBUNG NUMBER(18,2) NOT NULL DEFAULT 0 COMMENT 'Abschriftenbetrag ohne MWSt -  aus Marktabschriften COI ohne Werbung',
	EK_KB_STAMM NUMBER(18,4) NOT NULL WITH MASKING POLICY #unknown_policy,
	VK_BRUTTO_PK1 NUMBER(18,3) COMMENT 'Verkaufspreis Brutto des Artikels im jeweiligen Markt je Preiskategorie',
	VK_BRUTTO_PK4 NUMBER(18,3) COMMENT 'Verkaufspreis Brutto des Artikels im jeweiligen Markt je Preiskategorie',
	VK_NETTO_PK1 NUMBER(18,3) COMMENT 'Verkaufspreis Brutto des Artikels im jeweiligen Markt je Preiskategorie',
	VK_NETTO_PK4 NUMBER(18,3) COMMENT 'Verkaufspreis Brutto des Artikels im jeweiligen Markt je Preiskategorie',
	TOTAL_UMSATZ_NETTO NUMBER(18,4) NOT NULL COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag',
	TOTAL_UMSATZ_NETTO_AF NUMBER(18,4) NOT NULL COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag',
	TOTAL_UMSATZ_NETTO_SA NUMBER(18,4) NOT NULL COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag',
	TOTAL_ANZ_MARKT NUMBER(38,0) COMMENT 'Gibt an wie viele Märkte im rollierenden Jahr den betrachteten Artikel abverkauft haben',
	ANZ_KJWO_WUP_LISTUNG NUMBER(38,0) COMMENT 'Anzahl Wochen in denen dieser Artikel im abgefragten Zeitraum (12 Monate) gelistet wurde',
	ANZ_WUP_LISTUNG NUMBER(38,0) COMMENT 'Anzahl Märkte die diesen Artikel im abgefragten Zeitraum (12 Monate) gelistet haben',
	LAGER_PROZENT NUMBER(38,0) NOT NULL DEFAULT 100 COMMENT 'Lagerprozentsatz. Gibt an, wieviel Prozent der Restlaufzeit noch nicht abgelaufen sein darf, wenn der Artikel vom Lager ausgeliefert wird',
	KOL_LA_BZW NUMBER(38,5) NOT NULL,
	KOL_BST_BZW NUMBER(38,5) NOT NULL,
	SPANNE_EK1 NUMBER(38,5) NOT NULL WITH MASKING POLICY #unknown_policy,
	SPANNE_EK4 NUMBER(38,5) NOT NULL WITH MASKING POLICY #unknown_policy,
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ZEK_ID VARCHAR(3) COMMENT 'Zentraleinkäufer - ID: Diese ID ist nicht mit der Mitarbeiter - ID identisch',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	constraint PK_SAL_KMO primary key (MANDANT_ID, ART_ID, KJMO)
)COMMENT='TP2_AIS - Aggregat für die Sortimentsausschussliste im Einkauf. (KMO)'
;